<template>
  <section class="rbac-page">
    <header class="page-head"><div><router-link to="/super-admin/rbac">← 返回权限组织</router-link><h2>职位权限</h2></div><div class="object-switch"><div class="object-badge"><small>当前对象 · 职位</small><strong>{{ selectedPosition ? `${selectedPosition.name} · ${selectedPosition.department_name || '未分部门'}` : '请选择职位' }}</strong></div><select v-model.number="selectedPositionId" @change="loadPosition"><option v-for="p in positions" :key="p.id" :value="p.id">{{ p.name }} / {{ p.department_name || '未分部门' }}</option></select></div></header>
    <div v-if="error" class="banner banner--error">{{ error }}</div><div v-if="message" class="banner">{{ message }}</div>
    <section class="panel workbench">
      <div class="permission-pane"><div class="pane-title"><div><strong>授权边界内权限</strong><span>按业务域分组勾选</span></div></div>
        <div v-if="hiddenCount" class="boundary-note">医疗 / 仓储等 {{ hiddenCount }} 项权限不在此职位授权边界内，已隐藏</div>
        <div class="permission-groups"><section v-for="group in groups" :key="group.name"><h3>{{ group.name }}</h3><div class="permission-list"><label v-for="key in group.keys" :key="key" class="permission-item" :class="{active:key===activeKey}" @mouseenter="activeKey=key"><input type="checkbox" :checked="selected.includes(key)" @focus="activeKey=key" @change="toggle(key)"/><span>{{ label(key) }}</span></label></div></section></div>
        <div class="actions"><button class="button" :disabled="!selectedPositionId" @click="openDiff">保存职位权限</button><button class="button button--ghost danger-button" :disabled="!selectedPositionId" @click="confirmReset">重置为默认最低权限</button></div>
      </div>
      <aside class="help"><strong>权限说明</strong><template v-if="activeMeta"><h3>{{ activeMeta.label }}</h3><code>{{ activeKey }}</code><p>{{ activeMeta.desc }}</p><div class="boundary">能力边界：仅在当前职位允许的业务域内生效，数据范围仍由组织范围控制。</div><div v-if="activeMeta.danger" class="warning">⚠ 高危权限：授予前请确认岗位确有需要。</div></template><p v-else class="empty">将鼠标移到或聚焦任一权限，这里会显示中文含义与能力边界。</p></aside>
    </section>
    <PermissionDiffDialog :open="diffOpen" title="确认职位权限差异" :added="added" :removed="removed" :saving="saving" @cancel="diffOpen=false" @confirm="save" />
  </section>
</template>
<script lang="ts">
import { computed, defineComponent, onMounted, ref } from "vue";
import PermissionDiffDialog from "@/modules/super-admin/components/PermissionDiffDialog.vue";
import { superAdminApi } from "@/modules/super-admin/api/superAdminApi";
import type { RbacPosition } from "@/modules/super-admin/api/types";
import { GROUP_ORDER, PERMISSION_META, permissionGroups, permissionLabel } from "@/modules/super-admin/utils/permissionMeta";
export default defineComponent({name:"SuperAdminRbacPositions",components:{PermissionDiffDialog},setup(){
 const positions=ref<RbacPosition[]>([]),catalog=ref<string[]>([]),selected=ref<string[]>([]),snapshot=ref<string[]>([]),grantable=ref<string[]>([]);const selectedPositionId=ref(0),activeKey=ref(""),error=ref(""),message=ref(""),diffOpen=ref(false),saving=ref(false);
 const selectedPosition=computed(()=>positions.value.find(p=>p.id===selectedPositionId.value));const activeMeta=computed(()=>activeKey.value?(PERMISSION_META[activeKey.value]||{label:activeKey.value,desc:"暂无中文说明。",group:"其他"}):null);const visibleKeys=computed(()=>Array.from(new Set([...grantable.value,...selected.value])));const groups=computed(()=>permissionGroups(visibleKeys.value));const hiddenCount=computed(()=>catalog.value.filter(k=>!visibleKeys.value.includes(k)).length);const added=computed(()=>selected.value.filter(k=>!snapshot.value.includes(k)));const removed=computed(()=>snapshot.value.filter(k=>!selected.value.includes(k)));
 const loadPosition=async()=>{if(!selectedPositionId.value)return;try{const data=await superAdminApi.getPositionPermissions(selectedPositionId.value);selected.value=[...data.permissions];snapshot.value=[...data.permissions];grantable.value=[...data.grantableKeys];activeKey.value=visibleKeys.value[0]||"";error.value=""}catch(e){error.value=e instanceof Error?e.message:"加载职位权限失败"}};
 const load=async()=>{try{[positions.value,catalog.value]=await Promise.all([superAdminApi.getRbacPositions(),superAdminApi.getPermissionCatalog()]);if(positions.value.length){selectedPositionId.value=positions.value[0].id;await loadPosition()}}catch(e){error.value=e instanceof Error?e.message:"加载权限数据失败"}};
 const toggle=(key:string)=>{activeKey.value=key;selected.value=selected.value.includes(key)?selected.value.filter(v=>v!==key):[...selected.value,key]};const openDiff=()=>{diffOpen.value=true};
 const save=async()=>{saving.value=true;try{await superAdminApi.updatePositionPermissions(selectedPositionId.value,selected.value);snapshot.value=[...selected.value];diffOpen.value=false;message.value="职位权限已保存";error.value=""}catch(e){error.value=e instanceof Error?e.message:"保存职位权限失败";diffOpen.value=false}finally{saving.value=false}};
 const confirmReset=async()=>{if(!window.confirm("将该职位恢复为系统默认最低权限，当前自定义权限会被替换。确认继续？"))return;try{await superAdminApi.resetPositionDefaults(selectedPositionId.value);await loadPosition();message.value="已重置为默认最低权限"}catch(e){error.value=e instanceof Error?e.message:"重置失败"}};
 onMounted(()=>void load());return{positions,selectedPositionId,selectedPosition,selected,activeKey,activeMeta,groups,hiddenCount,diffOpen,saving,added,removed,label:permissionLabel,loadPosition,toggle,openDiff,save,confirmReset,error,message,GROUP_ORDER};
}});
</script>
<style scoped>
