ont-size:12px}.help h3{margin:14px 0 5px}.help code{color:#2263ad;background:#e6eff9;padding:3px 7px;border-radius:6px}.help p,.boundary{color:#4e6680;font-size:13px;line-height:1.65}.boundary{padding-top:10px;border-top:1px solid #d7e3f2}.warning{margin-top:10px;padding:9px;background:#fff3d8;border-radius:8px;color:#9b5700;font-size:12px;font-weight:800}.empty{color:#8090a3}.banner{padding:10px 12px;border:1px solid #cfe0f5;border-radius:9px;background:#eaf3fd;color:#1e5aa0}.banner--error{border-color:#fecaca;background:#fef2f2;color:#991b1b}@media(max-width:1000px){.page-head{align-items:stretch;flex-direction:column}.object-switch{align-items:stretch;flex-direction:column}.workbench{grid-template-columns:1fr}.help{position:static}}
</style>
